const ax = new Axes({ xRange: [-4, 4, 1], yRange: [0, 0.45, 0.1], xLength: 10, yLength: 4.4, tips: false });
const pdf = x => Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI);
const curve = ax.plot(pdf, { color: BLUE, numSamples: 200 });
const baseY = ax.c2p(0, 0)[1];
const bands = [];
const colors = [GREEN, YELLOW, ORANGE];
const labelsText = ['68% within ±1σ', '95% within ±2σ', '99.7% within ±3σ'];
for (let i = 0; i < 3; i++) {
  const k = i + 1;
  const vertices = [ax.c2p(-k, 0), ...Array.from({ length: 61 }, (_, j) => {
    const x = -k + (2 * k * j) / 60;
    return ax.c2p(x, pdf(x));
  }), ax.c2p(k, 0)];
  const region = new Polygon({ vertices, color: colors[i] });
  region.setFill(colors[i], 0.14 - i * 0.025).setStrokeWidth(1);
  bands.push(region);
}
const title = new Text({ text: '68–95–99.7 rule', color: WHITE, fontSize: 34 }).moveTo([0, 3.25, 0]);
const labels = labelsText.map((s, i) => new Text({ text: s, color: colors[i], fontSize: 22 }).moveTo([0, 2.65 - i * 0.38, 0]));
const meanLine = new Line({ start: ax.c2p(0, 0), end: ax.c2p(0, pdf(0)), color: WHITE });
const meanDot = new Dot({ point: ax.c2p(0, 0), color: WHITE });
scene.add(ax, bands[2], bands[1], bands[0], curve, meanLine, meanDot, title, ...labels);
makeDraggable(meanDot, scene, { constrainX: [-4, 4], constrainY: [baseY, baseY] });
await scene.wait(999999);
